  consulta.etiquetas.every((etiqueta) => recurso.etiquetas[etiqueta.clave] === etiqueta.valor);

assert.deepStrictEqual(
  consulta.recursos.filter(coincide).map((recurso) => recurso.id),
  ["i-0a1", "i-0a2"],
);

const soloEntorno = { id: "i-0b1", etiquetas: { Environment: "lab" } };
