// Decide qué recursos entran en el grupo del laboratorio. Corrige su defecto principal.
export interface Recurso {
  readonly id: string;
  readonly etiquetas: Readonly<Record<string, string>>;
}

export function recursosDelGrupo(
  recursos: readonly Recurso[],
  etiquetasRequeridas: Readonly<Record<string, string>>,
): string[] {
  const exigidas = Object.entries(etiquetasRequeridas);

  return recursos
    .filter((recurso) => exigidas.some(([clave, valor]) => recurso.etiquetas[clave] === valor))
    .map((recurso) => recurso.id);
}

solution.code:
export interface Recurso {
  readonly id: string;
  readonly etiquetas: Readonly<Record<string, string>>;
}

export function recursosDelGrupo(
  recursos: readonly Recurso[],
  etiquetasRequeridas: Readonly<Record<string, string>>,
): string[] {
  const exigidas = Object.entries(etiquetasRequeridas);

  return recursos
    .filter((recurso) => exigidas.every(([clave, valor]) => recurso.etiquetas[clave] === valor))
    .map((recurso) => recurso.id);
}

spec.code:
const recursos = [
  { id: "i-0a1", etiquetas: { Environment: "lab", Owner: "equipo-datos" } },
  { id: "i-0a2", etiquetas: { Environment: "lab", Owner: "equipo-datos" } },
  { id: "i-0a3", etiquetas: { Environment: "prod", Owner: "equipo-datos" } },
  { id: "i-0a4", etiquetas: { Environment: "lab" } },
];

assert.deepStrictEqual(
  recursosDelGrupo(recursos, { Environment: "lab", Owner: "equipo-datos" }),
  ["i-0a1", "i-0a2"],
);

const recursos = [
  { id: "i-0a3", etiquetas: { Environment: "prod", Owner: "equipo-datos" } },
];

assert.deepStrictEqual(recursosDelGrupo(recursos, { Environment: "lab", Owner: "equipo-datos" }), []);

const recursos = [{ id: "i-0a4", etiquetas: { Environment: "lab" } }];

assert.deepStrictEqual(
  recursosDelGrupo(recursos, { Environment: "lab", Owner: "equipo-datos" }),
  [],
);

const recursos = [
  { id: "i-0a1", etiquetas: { Environment: "lab", Owner: "equipo-datos" } },
  { id: "i-0a2", etiquetas: { Environment: "prod", Owner: "equipo-datos" } },
];

recursosDelGrupo(recursos, { Environment: "lab", Owner: "equipo-datos" });

assert.deepStrictEqual(
  recursos.map((recurso) => recurso.id),
  ["i-0a1", "i-0a2"],
);

const recursos = [
  { id: "i-0a1", etiquetas: { Environment: "lab", Owner: "equipo-datos" } },
];

assert.deepStrictEqual(recursosDelGrupo(recursos, { environment: "lab" }), []);
